import { Vector3 } from 'three';

export class GameLoop {
    private lastTime: number = 0;
    private accumulator: number = 0;
    private fixedStep: number = 1 / 60;
    private maxSubSteps: number = 5;

    private timescale: number = 1.0;
    private isPaused: boolean = false;

    constructor() {
        this.lastTime = performance.now();
    }

    public update(): void {
        if (this.isPaused) return;

        const currentTime: number = performance.now();
        let deltaTime: number = (currentTime - this.lastTime) * this.timescale;
        this.lastTime = currentTime;

        // Cap delta time to prevent huge jumps on tab switch
        deltaTime = Math.min(deltaTime, 0.1);

        this.accumulator += deltaTime;

        while (this.accumulator >= this.fixedStep && this.maxSubSteps > 0) {
            this.step(this.fixedStep);
            this.accumulator -= this.fixedStep;
            this.maxSubSteps--;
        }

        this.maxSubSteps = 5; // Reset for next frame
    }

    private step(deltaTime: number): void {
        // Override in subclass
    }

    public setTimescale(scale: number): void {
        this.timescale = Math.max(0, Math.min(1, scale));
    }

    public getTimescale(): number {
        return this.timescale;
    }

    public pause(): void {
        this.isPaused = true;
    }

    public resume(): void {
        this.isPaused = false;
        this.lastTime = performance.now();
    }

    public reset(): void {
        this.accumulator = 0;
        this.timescale = 1.0;
        this.lastTime = performance.now();
    }
}

import { Vector3, Color } from 'three';
import { Enemy, EnemyType } from './Enemy';
import { ObjectPool } from '../../shared/core/ObjectPool';

export class Boss extends Enemy {
    private shootTimer: number = 0;
    private shootInterval: number = 1.5; // seconds
    private patternPhase: number = 0; // 0: spread, 1: aimed, 2: spiral

    constructor(pool: ObjectPool<Enemy>, position: Vector3) {
        super(pool, position);
        this.type = EnemyType.BOSS;
        this.health = 50;
        this.maxHealth = 50;
        this.scoreValue = 100;

        // Boss-specific properties
        this.mesh.scale.set(2.5, 2.5, 1);
    }

    public update(deltaTime: number): void {
        super.update(deltaTime);

        // Boss movement pattern - oscillates horizontally
        const time = this.gameTime;
        this.position.x = this.basePosition.x + Math.sin(time * 0.5) * 20;

        // Shooting logic with pattern phases
        this.shootTimer += deltaTime;
        if (this.shootTimer >= this.shootInterval) {
            this.shootTimer = 0;
            this.fire();
        }
    }

    private fire(): void {
        const bulletSpeed = -150; // upward

        switch (this.patternPhase) {
            case 0: // Spread pattern
                for (let i = -2; i <= 2; i++) {
                    this.createBullet(i * 30, bulletSpeed);
                }
                break;

            case 1: // Aimed at player
                const targetX = this.game?.player?.position.x || 0;
                const dx = (targetX - this.position.x) / Math.abs(targetX - this.position.x + 0.001);
                this.createBullet(dx * 50, bulletSpeed);
                break;

            case 2: // Spiral pattern
                for (let i = 0; i < 8; i++) {
                    const angle = (i / 8) * Math.PI * 2;
                    const vx = Math.cos(angle) * 40;
                    this.createBullet(vx, bulletSpeed);
                }
                break;
        }

        // Cycle pattern phase
        this.patternPhase = (this.patternPhase + 1) % 3;
    }

    private createBullet(lateralVelocity: number, verticalVelocity: number): void {
        const bullet = this.pool.get();
        if (bullet && bullet instanceof BulletClass) {
            bullet.position.copy(this.position);
            bullet.position.y -= 20; // Start above boss
            bullet.velocity.set(lateralVelocity, verticalVelocity, 0);
            bullet.active = true;
            bullet.ownerType = 'enemy';
        }
    }

    public onDeath(): void {
        super.onDeath();

        // Boss death triggers massive shockwave
        if (this.game) {
            this.game.vfx.shockwaves.spawn(this.position.clone(), 5);
            this.game.vfx.particles.spawnExplosion(
                this.position.clone(), 
                100, 
                new Color('#FFD700') // Gold explosion
            );
        }
    }

    public dispose(): void {
        super.dispose();
    }
}

