export class Game extends GameLoop {
    // Three.js core
    private scene: THREE.Scene;
    private camera: THREE.PerspectiveCamera;
    private renderer: THREE.WebGLRenderer;
    private composer: EffectComposer;

    // Systems
    private input: InputManager;
    private collision: CollisionSystem;
    private score: ScoreSystem;
    private memory: MemoryManager;

    // VFX systems
    public vfx: {
        particles: ParticleSystem;
        shake: CameraShake;
        hitStop: HitStop;
        trails: MotionTrails;
        shockwaves: ShockwaveRings;
        floatingText: FloatingText;
    };

    // Game entities
    private player: Player | null = null;
    private enemies: Enemy[] = [];
    private bullets: Bullet[] = [];
    private powerups: Powerup[] = [];

    // Pooling
    private enemyPool: ObjectPool<Enemy>;
    private bulletPool: ObjectPool<Bullet>;
    private powerupPool: ObjectPool<Powerup>;

    // Game state
    private gameState: 'menu' | 'playing' | 'gameover' | 'victory' = 'menu';
    private waveNumber: number = 1;
    private lives: number = 3;
    private score: number = 0;
    private highScore: number = parseInt(localStorage.getItem('spaceInvadersHighScore') || '0');

    // Wave management
    private enemiesToSpawn: EnemyType[] = [];
    private spawnTimer: number = 0;
    private formationDirection: number = 1;
    private formationSpeed: number = 20;
    private formationDropDistance: number = 5;

    // Audio context
    private audioContext: AudioContext | null = null;

    // Constants
    private readonly SCREEN_WIDTH: number = 40;
    private readonly SCREEN_HEIGHT: number = 60;
    private readonly PLAYER_Y: number = -28;
    private readonly ENEMY_ROW_COUNT: number = 5;
    private readonly ENEMY_COL_COUNT: number = 11;
    private readonly ENEMY_SPACING_X: number = 4;
    private readonly ENEMY_SPACING_Y: number = 3;

    constructor() {
        super();

        // Initialize Three.js scene
        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x000011);

        // Camera setup
        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        this.camera.position.z = 30;

        // Renderer with PBR support
        this.renderer = new THREE.WebGLRenderer({ antialias: false });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.getElementById('game-container')!.appendChild(this.renderer.domElement);

        // Post-processing stack
        this.composer = new EffectComposer(this.renderer);
        const bloomPass = new UnrealBloomPass(
            new THREE.Vector2(window.innerWidth, window.innerHeight),
            1.5,
            0.4,
            0.15
        );
        this.composer.addPass(new RenderPass(this.scene, this.camera));
        this.composer.addPass(bloomPass);

        // Initialize systems
        this.input = new InputManager();
        this.collision = new CollisionSystem();
        this.memory = new MemoryManager();

        this.vfx = {
            particles: new ParticleSystem(this.scene, 500),
            shake: new CameraShake(),
            hitStop: new HitStop(),
            trails: new MotionTrails(),
            shockwaves: new ShockwaveRings(this.scene),
            floatingText: new FloatingText()
        };

        // Initialize pools
        this.enemyPool = new ObjectPool(() => {
            const enemy = new Enemy(
                this,
                new THREE.Vector3(0, 0, 0)
            );
            return enemy;
        }, 60);

        this.bulletPool = new ObjectPool(() => {
            const bullet = new Bullet(
                this,
                new THREE.Vector3(0, 0, 0)
            );
            return bullet;
        }, 50);

        this.powerupPool = new ObjectPool(() => {
            const powerup = new Powerup(this);
            return powerup;
        }, 10);

        // Setup lighting
        const ambientLight = new THREE.AmbientLight(0x404080, 0.5);
        this.scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(10, 20, 10);
        this.scene.add(directionalLight);

        // Setup stars background
        this.setupStars();

        // Event listeners
        window.addEventListener('resize', () => this.onResize());

        // Hide loading screen
        setTimeout(() => {
            document.getElementById('loading')!.style.display = 'none';
        }, 500);

        // Start game loop
        this.lastTime = performance.now();
    }

    private setupStars(): void {
        const starGeometry = new THREE.BufferGeometry();
        const starCount = 1000;
        const positions = new Float32Array(starCount * 3);
        const colors = new Float32Array(starCount * 3);

        for (let i = 0; i < starCount; i++) {
            const i3 = i * 3;

            // Random position in a large sphere
            positions[i3] = (Math.random() - 0.5) * 200;
            positions[i3 + 1] = (Math.random() - 0.5) * 200;
            positions[i3 + 2] = (Math.random() - 0.5) * 200;

            // Random color with slight blue tint
            const brightness = Math.random();
            colors[i3] = brightness * 0.8 + 0.2;
            colors[i3 + 1] = brightness * 0.8 + 0.2;
            colors[i3 + 2] = brightness * 1.0 + 0.5;
        }

        starGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        starGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const starMaterial = new THREE.PointsMaterial({
            size: 0.5,
            vertexColors: true,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });

        const stars = new THREE.Points(starGeometry, starMaterial);
        this.scene.add(stars);
    }

    public start(): void {
        this.resetGame();
        this.gameState = 'playing';

        document.getElementById('main-menu')!.classList.add('hidden');
        document.getElementById('game-over')!.classList.add('hidden');

        // Initialize audio context on user interaction
        if (!this.audioContext) {
            this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        }

        this.spawnWave();
    }

    public restart(): void {
        this.start();
    }

    public showHighScore(): void {
        alert(`High Score: ${this.highScore}`);
    }

    private resetGame(): void {
        // Clear existing entities
        if (this.player) {
            this.scene.remove(this.player.mesh);
            this.player.dispose();
        }

        this.enemies.forEach(e => this.scene.remove(e.mesh));
        this.bullets.forEach(b => this.scene.remove(b.mesh));
        this.powerups.forEach(p => this.scene.remove(p.mesh));

        this.enemies = [];
        this.bullets = [];
        this.powerups = [];

        // Reset pools
        this.enemyPool.reset();
        this.bulletPool.reset();
        this.powerupPool.reset();

        // Reset game state
        this.waveNumber = 1;
        this.lives = 3;
        this.score = 0;
        this.formationDirection = 1;

        this.updateHUD();
    }

    private spawnWave(): void {
        // Generate enemy formation based on wave number
        const initialCount = this.ENEMY_ROW_COUNT * this.ENEMY_COL_COUNT;
        const aliveCount = this.enemies.filter(e => e.active).length;

        // Calculate current speed (increases with difficulty)
        const difficultyMultiplier = 1 + (this.waveNumber - 1) * 0.1;
        this.formationSpeed = 20 * difficultyMultiplier;

        // Spawn enemies in grid formation
        for (let row = 0; row < this.ENEMY_ROW_COUNT; row++) {
            for (let col = 0; col < this.ENEMY_COL_COUNT; col++) {
                const position = new THREE.Vector3(
                    -15 + col * this.ENEMY_SPACING_X,
                    20 - row * this.ENEMY_SPACING_Y,
                    0
                );

                // Determine enemy type based on row and wave
                let type: EnemyType = EnemyType.GRUNT;
                if (this.waveNumber >= 3 && row === 0) {
                    type = Math.random() < 0.3 ? EnemyType.ELITE : EnemyType.GRUNT;
                } else if (this.waveNumber % 3 === 0 && row === 0 && col === 5) {
                    // Spawn boss every 3rd wave at center top
                    const boss = new Boss(this.enemyPool, position);
                    this.enemies.push(boss);
                    continue;
                }

                const enemy = this.enemyPool.get();
                if (enemy) {
                    enemy.initialize(position, type, this.waveNumber);
                    this.enemies.push(enemy);
                }
            }
        }

        this.updateHUD();
    }

    private updateFormation(deltaTime: number): void {
        const activeEnemies = this.enemies.filter(e => e.active && !e.isBoss);

        if (activeEnemies.length === 0) return;

        // Check edge boundaries
        let hitEdge = false;
        for (const enemy of activeEnemies) {
            if ((this.formationDirection > 0 && enemy.position.x > this.SCREEN_WIDTH / 2 - 2) ||
                (this.formationDirection < 0 && enemy.position.x < -this.SCREEN_WIDTH / 2 + 2)) {
                hitEdge = true;
                break;
            }
        }

        if (hitEdge) {
            this.formationDirection *= -1;

            // Drop all enemies down
            for (const enemy of activeEnemies) {
                enemy.position.y -= this.formationDropDistance;

                // Game over if enemies reach player line
                if (enemy.position.y < this.PLAYER_Y + 5) {
                    this.triggerGameOver();
                    return;
                }
            }

            // Increase speed slightly on each drop
            this.formationSpeed *= 1.02;
        } else {
            // Move formation horizontally
            for (const enemy of activeEnemies) {
                enemy.position.x += this.formationDirection * this.formationSpeed * deltaTime;
            }
        }
    }

    private updatePlayer(deltaTime: number): void {
        if (!this.player || !this.player.active) return;

        const moveSpeed = 30;
        let velocityX = 0;

        // Keyboard input
        if (this.input.isKeyDown('ArrowLeft') || this.input.isKeyDown('a')) {
            velocityX -= moveSpeed;
        }
        if (this.input.isKeyDown('ArrowRight') || this.input.isKeyDown('d')) {
            velocityX += moveSpeed;
        }

        // Gamepad input
        const gamepad = this.input.getGamepad();
        if (gamepad) {
            const axisValue = gamepad.axes[0];
            if (Math.abs(axisValue) > 0.15) {
                velocityX = axisValue * moveSpeed;
            }
        }

        // Apply movement with boundary constraints
        this.player.position.x += velocityX * deltaTime;
        this.player.position.x = Math.max(-this.SCREEN_WIDTH / 2 + 2, 
                                          Math.min(this.SCREEN_WIDTH / 2 - 2, 
                                                  this.player.position.x));

        // Shooting input
        if (this.input.isKeyDown('Space') || this.input.isGamepadButtonPressed(0)) {
            this.fireBullet();
        }
    }

    private fireBullet(): void {
        if (!this.player || !this.player.active) return;

        const bullet = this.bulletPool.get();
        if (bullet && bullet instanceof Bullet) {
            bullet.initialize(this.player.position.clone(), -200, 'player');
            this.bullets.push(bullet);

            // Play shoot sound
            this.playShootSound();
        }
    }

    private updateBullets(deltaTime: number): void {
        for (const bullet of this.bullets) {
            if (!bullet.active) continue;

            bullet.position.y += bullet.velocity.y * deltaTime;

            // Remove bullets off screen
            if (bullet.position.y < -30 || bullet.position.y > 30) {
                bullet.deactivate();
            }
        }

        // Cleanup inactive bullets from array
        this.bullets = this.bullets.filter(b => b.active);
    }

    private updateEnemies(deltaTime: number): void {
        for (const enemy of this.enemies) {
            if (!enemy.active) continue;

            enemy.update(deltaTime);

            // Enemy shooting logic
            if (Math.random() < 0.01 * this.waveNumber && !enemy.isBoss) {
                const bullet = this.bulletPool.get();
                if (bullet && bullet instanceof Bullet) {
                    bullet.initialize(enemy.position.clone(), -150, 'enemy');
                    this.bullets.push(bullet);
                }
            }

            // Boss shooting handled in Boss class
        }
    }

    private checkCollisions(): void {
        const activeBullets = this.bullets.filter(b => b.active);
        const activeEnemies = this.enemies.filter(e => e.active && !e.isBoss);

        // Bullet vs Enemy collisions
        for (const bullet of activeBullets) {
            if (!bullet.active || bullet.ownerType !== 'player') continue;

            for (const enemy of activeEnemies) {
                if (!enemy.active) continue;

                const bulletBox = new THREE.Box3().setFromObject(bullet.mesh);
                const enemyBox = new THREE.Box3().setFromObject(enemy.mesh);

                if (bulletBox.intersectsBox(enemyBox)) {
                    // Hit enemy
                    bullet.deactivate();
                    this.damageEnemy(enemy, 10);

                    // Particle effect
                    this.vfx.particles.spawnExplosion(
                        bullet.position.clone(),
                        5,
                        new THREE.Color('#ff0')
                    );

                    break;
                }
            }
        }

        // Bullet vs Boss collision
        const boss = this.enemies.find(e => e.isBoss);
        if (boss && boss.active) {
            for (const bullet of activeBullets) {
                if (!bullet.active || bullet.ownerType !== 'player') continue;

                const bulletBox = new THREE.Box3().setFromObject(bullet.mesh);
                const bossBox = new THREE.Box3().setFromObject(boss.mesh);

                if (bulletBox.intersectsBox(bossBox)) {
                    bullet.deactivate();
                    this.damageEnemy(boss, 10);

                    this.vfx.particles.spawnExplosion(
                        bullet.position.clone(),
                        5,
                        new THREE.Color('#ffd700')
                    );

                    break;
                }
            }
        }

        // Enemy Bullet vs Player collision
        const playerBullet = activeBullets.find(b => b.active && b.ownerType === 'enemy');
        if (playerBullet && this.player?.active) {
            const bulletBox = new THREE.Box3().setFromObject(playerBullet.mesh);
            const playerBox = new THREE.Box3().setFromObject(this.player.mesh);

            if (bulletBox.intersectsBox(playerBox)) {
                playerBullet.deactivate();
                this.damagePlayer(10);
            }
        }

        // Enemy vs Player collision (crash)
        for (const enemy of activeEnemies) {
            if (!enemy.active) continue;

            const enemyBox = new THREE.Box3().setFromObject(enemy.mesh);
            const playerBox = new THREE.Box3().setFromObject(this.player!.mesh);

            if (enemyBox.intersectsBox(playerBox)) {
                this.damagePlayer(20);
                enemy.deactivate();

                this.vfx.particles.spawnExplosion(
                    enemy.position.clone(),
                    15,
                    new THREE.Color('#f00')
                );
            }
        }

        // Powerup collection
        for (const powerup of this.powerups) {
            if (!powerup.active) continue;

            const powerupBox = new THREE.Box3().setFromObject(powerup.mesh);
            const playerBox = new THREE.Box3().setFromObject(this.player!.mesh);

            if (powerupBox.intersectsBox(playerBox)) {
                this.activatePowerup(powerup.type);
                powerup.deactivate();
            }
        }
    }

    private damageEnemy(enemy: Enemy, damage: number): void {
        enemy.health -= damage;

        // Score calculation based on enemy type
        const baseScore = enemy.scoreValue;
        this.score += baseScore;

        // Combo system
        if (this.score.comboTimer > 0) {
            this.score.comboCount++;
            this.score.comboMultiplier = Math.min(5, 1 + this.score.comboCount * 0.2);
        } else {
            this.score.comboCount = 1;
            this.score.comboMultiplier = 1;
        }

        this.score.comboTimer = 3.0; // 3 second combo window

        const finalScore = Math.floor(baseScore * this.score.comboMultiplier);
        this.score.update(finalScore, enemy.position.clone());

        if (enemy.health <= 0) {
            this.killEnemy(enemy);
        }
    }

    private killEnemy(enemy: Enemy): void {
        enemy.deactivate();

        // Explosion effect
        this.vfx.particles.spawnExplosion(
            enemy.position.clone(),
            15,
            new THREE.Color(enemy.type === EnemyType.BOSS ? '#ffd700' : 
                          enemy.type === EnemyType.ELITE ? '#f0f' : '#0f0')
        );

        // Shockwave on boss death
        if (enemy.isBoss) {
            this.vfx.shockwaves.spawn(enemy.position.clone(), 3);
            this.vfx.hitStop.trigger(0.2);
        } else {
            // Chance to drop powerup
            if (Math.random() < 0.05) {
                const powerup = this.powerupPool.get();
                if (powerup) {
                    powerup.initialize(enemy.position.clone());
                    this.powerups.push(powerup);
                }
            }
        }

        // Check wave completion
        const remainingEnemies = this.enemies.filter(e => e.active && !e.isBoss).length;
        const bossAlive = this.enemies.some(e => e.isBoss && e.active);

        if (remainingEnemies === 0 && !bossAlive) {
            this.completeWave();
        }
    }

    private damagePlayer(damage: number): void {
        if (!this.player || !this.player.active) return;

        this.lives -= Math.floor(damage / 10);

        // Camera shake and hit stop
        this.vfx.shake.trigger(2.0);
        this.vfx.hitStop.trigger(0.3);

        // Explosion effect at player position
        this.vfx.particles.spawnExplosion(
            this.player.position.clone(),
            20,
            new THREE.Color('#f00')
        );

        if (this.lives <= 0) {
            this.triggerGameOver();
        } else {
            // Respawn player with invulnerability
            this.player.respawn();
            this.updateHUD();
        }
    }

    private activatePowerup(type: PowerupType): void {
        const indicator = document.getElementById('powerup-indicator')!;

        switch (type) {
            case PowerupType.SPREAD_SHOT:
                this.player!.activateSpreadShot(10);
                indicator.textContent = 'SPREAD SHOT';
                break;
            case PowerupType.RAPID_FIRE:
                this.player!.activateRapidFire(8);
                indicator.textContent = 'RAPID FIRE';
                break;
            case PowerupType.EXTRA_LIFE:
                this.lives = Math.min(5, this.lives + 1);
                indicator.textContent = '+1 LIFE';
                break;
            case PowerupType.SHIELD_BOOST:
                // Shield regeneration handled in Player class
                indicator.textContent = 'SHIELD BOOST';
                break;
        }

        indicator.classList.add('active');
        setTimeout(() => {
            indicator.classList.remove('active');
        }, 2000);

        this.playPowerupSound();
    }

    private completeWave(): void {
        // Clear remaining enemies
        for (const enemy of this.enemies) {
            if (enemy.active) {
                enemy.deactivate();
                this.vfx.particles.spawnExplosion(
                    enemy.position.clone(),
                    10,
                    new THREE.Color('#0ff')
                );
            }
        }

        // Bonus score for wave completion
        const bonus = this.waveNumber * 100;
        this.score.update(bonus, new THREE.Vector3(0, 10, 0));

        // Increase wave number
        this.waveNumber++;

        if (this.waveNumber > 10) {
            // Victory condition
            this.triggerVictory();
        } else {
            // Spawn next wave after delay
            setTimeout(() => {
                this.spawnWave();
            }, 3000);
        }
    }

    private triggerGameOver(): void {
        this.gameState = 'gameover';

        if (this.score > this.highScore) {
            this.highScore = Math.floor(this.score);
            localStorage.setItem('spaceInvadersHighScore', this.highScore.toString());
        }

        document.getElementById('final-score')!.textContent = Math.floor(this.score).toString();
        document.getElementById('game-over')!.classList.remove('hidden');

        // Massive explosion at player position
        if (this.player) {
            this.vfx.particles.spawnExplosion(
                this.player.position.clone(),
                50,
                new THREE.Color('#f00')
            );
        }

        this.updateHUD();
    }

    private triggerVictory(): void {
        this.gameState = 'victory';

        // Victory celebration
        for (let i = 0; i < 5; i++) {
            setTimeout(() => {
                const position = new THREE.Vector3(
                    (Math.random() - 0.5) * 40,
                    (Math.random() - 0.5) * 20,
                    0
                );
                this.vfx.particles.spawnExplosion(position, 30, new THREE.Color('#ffd700'));
            }, i * 500);
        }

        setTimeout(() => {
            document.getElementById('game-over')!.classList.remove('hidden');
            document.querySelector('.gameover-text')!.textContent = 'VICTORY!';
            document.querySelector('.final-score')!.innerHTML = `Final Score: ${Math.floor(this.score)}`;
        }, 5000);
    }

    private updateHUD(): void {
        document.getElementById('score-display')!.textContent = Math.floor(this.score).toString();
        document.getElementById('high-score-display')!.textContent = this.highScore.toString();
        document.getElementById('wave-display')!.textContent = this.waveNumber.toString();
        document.getElementById('lives-display')!.textContent = this.lives.toString();

        // Update combo counter
        const comboCounter = document.getElementById('combo-counter')!;
        if (this.score.comboCount > 1) {
            comboCounter.textContent = `x${this.score.comboMultiplier.toFixed(1)}`;
            comboCounter.classList.add('active');
        } else {
            comboCounter.classList.remove('active');
        }
    }

    private playShootSound(): void {
        if (!this.audioContext) return;

        const oscillator = this.audioContext.createOscillator();
        const gainNode = this.audioContext.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(this.audioContext.destination);

        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(800, this.audioContext.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(200, this.audioContext.currentTime + 0.1);

        gainNode.gain.setValueAtTime(0.3, this.audioContext.currentTime);
        gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.1);

        oscillator.start(this.audioContext.currentTime);
        oscillator.stop(this.audioContext.currentTime + 0.1);
    }

    private playPowerupSound(): void {
        if (!this.audioContext) return;

        const now = this.audioContext.currentTime;

        // Arpeggiated sequence
        [261.63, 329.63, 392.00, 523.25].forEach((freq, i) => {
            const oscillator = this.audioContext.createOscillator();
            const gainNode = this.audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(this.audioContext.destination);

            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(freq, now + i * 0.1);

            gainNode.gain.setValueAtTime(0.2, now + i * 0.1);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + i * 0.1 + 0.3);

            oscillator.start(now + i * 0.1);
            oscillator.stop(now + i * 0.1 + 0.3);
        });
    }

    private onResize(): void {
        this.camera.aspect = window.innerWidth / window.innerHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.composer.setSize(window.innerWidth, window.innerHeight);
    }

    public update(deltaTime: number): void {
        if (this.gameState !== 'playing') return;

        // Update systems
        this.updatePlayer(deltaTime);
        this.updateBullets(deltaTime);
        this.updateEnemies(deltaTime);
        this.updateFormation(deltaTime);

        // Check collisions
        this.checkCollisions();

        // Update VFX systems
        this.vfx.particles.update(deltaTime);
        this.vfx.shake.update(deltaTime, this.camera.position);
        this.vfx.hitStop.update(deltaTime);
        this.vfx.trails.update(deltaTime);
        this.vfx.shockwaves.update(deltaTime);
        this.vfx.floatingText.update(deltaTime);

        // Update combo timer
        if (this.score.comboTimer > 0) {
            this.score.comboTimer -= deltaTime;
            if (this.score.comboTimer <= 0) {
                this.score.comboCount = 0;
                this.score.comboMultiplier = 1;
            }
        }

        // Update powerups
        for (const powerup of this.powerups) {
            if (powerup.active) {
                powerup.update(deltaTime);
            }
        }
        this.powerups = this.powerups.filter(p => p.active);
    }

    public render(): void {
        // Apply camera shake
        const shakeOffset = this.vfx.shake.getShakeOffset();
        this.camera.position.x += shakeOffset.x;
        this.camera.position.y += shakeOffset.y;

        // Render scene with post-processing
        this.composer.render();

        // Reset camera position
        this.camera.position.x -= shakeOffset.x;
        this.camera.position.y -= shakeOffset.y;
    }

    public dispose(): void {
        // Dispose all Three.js resources
        this.memory.disposeGame();

        if (this.player) {
            this.scene.remove(this.player.mesh);
            this.player.dispose();
        }

        this.enemies.forEach(e => {
            this.scene.remove(e.mesh);
            e.dispose();
        });

        this.bullets.forEach(b => {
            this.scene.remove(b.mesh);
            b.dispose();
        });

        this.powerups.forEach(p => {
            this.scene.remove(p.mesh);
            p.dispose();
        });

        // Dispose post-processing
        this.composer.dispose();
        this.renderer.dispose();

        window.removeEventListener('resize', () => this.onResize());
    }
}

// Powerup types enum
export enum PowerupType {
    SPREAD_SHOT,
    RAPID_FIRE,
    EXTRA_LIFE,
    SHIELD_BOOST
}

// Powerup class for floating power-ups
class Powerup extends THREE.Mesh {
    private type: PowerupType;
    private velocityY: number = -50;
    private lifetime: number = 10; // seconds
    private active: boolean = false;

    constructor(game: Game) {
        const geometry = new THREE.RingGeometry(1, 1.5, 8);
        let color = new THREE.Color();

        switch (game.score.comboCount % 4) {
            case 0: color = new THREE.Color('#f0f'); break; // Spread shot
            case 1: color = new THREE.Color('#ff0'); break; // Rapid fire
            case 2: color = new THREE.Color('#0f0'); break; // Extra life
            case 3: color = new THREE.Color('#0ff'); break; // Shield boost
        }

        const material = new THREE.MeshStandardMaterial({
            color: color,
            emissive: color,
            emissiveIntensity: 2,
            side: THREE.DoubleSide
        });

        super(geometry, material);

        this.type = PowerupType.SPREAD_SHOT; // Default
    }

    public initialize(position: THREE.Vector3): void {
        this.position.copy(position);
        this.active = true;
        this.lifetime = 10;

        // Random power-up type
        this.type = PowerupType[this.score.comboCount % 4] as PowerupType;
    }

    public update(deltaTime: number): void {
        this.position.y += this.velocityY * deltaTime;
        this.lifetime -= deltaTime;

        if (this.lifetime <= 0) {
            this.active = false;
        }
    }

    public deactivate(): void {
        this.active = false;
    }

    public dispose(): void {
        this.geometry.dispose();
        this.material.dispose();
    }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';

import { GameLoop } from '../shared/core/GameLoop';
import { InputManager } from '../shared/core/InputManager';
import { ObjectPool } from '../shared/core/ObjectPool';
import { MemoryManager } from '../shared/core/MemoryManager';
import { ParticleSystem } from '../shared/vfx/ParticleSystem';
import { CameraShake } from '../shared/vfx/CameraShake';
import { HitStop } from '../shared/vfx/HitStop';
import { MotionTrails } from '../shared/vfx/MotionTrails';
import { ShockwaveRings } from '../shared/vfx/ShockwaveRings';
import { FloatingText } from '../shared/vfx/FloatingText';
import { createEnemyTexture, createShieldTexture, createPowerupTexture } from '../shared/utils/ProceduralTextures';

import { Player } from './Entities/Player';
import { Enemy, EnemyType } from './Enemies/Enemy';
import { Boss } from './Enemies/Boss';
import { Bullet } from './Projectiles/Bullet';
import { Powerup, PowerupType } from './Entities/Powerup';
import { CollisionSystem } from './Systems/CollisionSystem';
import { ScoreSystem } from './Systems/ScoreSystem';

export class Game extends GameLoop {
    // Three.js core
    private scene: THREE.Scene;
    private camera: THREE.PerspectiveCamera;
    private renderer: THREE.WebGLRenderer;
    private composer: EffectComposer;

    // Systems
    private input: InputManager;
    private collision: CollisionSystem;
    private score: ScoreSystem;
    private memory: MemoryManager;

    // VFX systems
    public vfx: {
        particles: ParticleSystem;
        shake: CameraShake;
        hitStop: HitStop;
        trails: MotionTrails;
        shockwaves: ShockwaveRings;
        floatingText: FloatingText;
    };

    // Game entities
    private player: Player | null = null;
    private enemies: Enemy[] = [];
    private bullets: Bullet[] = [];
    private powerups: Powerup[] = [];

    // Pooling
    private enemyPool: ObjectPool<Enemy>;
    private bulletPool: ObjectPool<Bullet>;
    private powerupPool: ObjectPool<Powerup>;

    // Game state
    private gameState: 'menu' | 'playing' | 'gameover' | 'victory' = 'menu';
    private waveNumber: number = 1;
    private lives: number = 3;
    private score: number = 0;
    private highScore: number = parseInt(localStorage.getItem('spaceInvadersHighScore') || '0');

    // Wave management
    private enemiesToSpawn: EnemyType[] = [];
    private spawnTimer: number = 0;
    private formationDirection: number = 1;
    private formationSpeed: number = 20;
    private formationDropDistance: number = 5;

    // Audio context
    private audioContext: AudioContext | null = null;

    // Constants
    private readonly SCREEN_WIDTH: number = 40;
    private readonly SCREEN_HEIGHT: number = 60;
    private readonly PLAYER_Y: number = -28;
    private readonly ENEMY_ROW_COUNT: number = 5;
    private readonly ENEMY_COL_COUNT: number = 11;
    private readonly ENEMY_SPACING_X: number = 4;
    private readonly ENEMY_SPACING_Y: number = 3;

    constructor() {
        super();

        // Initialize Three.js scene
        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x000011);

        // Camera setup
        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        this.camera.position.z = 30;

        // Renderer with PBR support
        this.renderer = new THREE.WebGLRenderer({ antialias: false });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.getElementById('game-container')!.appendChild(this.renderer.domElement);

        // Post-processing stack
        this.composer = new EffectComposer(this.renderer);
        const bloomPass = new UnrealBloomPass(
            new THREE.Vector2(window.innerWidth, window.innerHeight),
            1.5,
            0.4,
            0.15
        );
        this.composer.addPass(new RenderPass(this.scene, this.camera));
        this.composer.addPass(bloomPass);

        // Initialize systems
        this.input = new InputManager();
        this.collision = new CollisionSystem();
        this.memory = new MemoryManager();

        this.vfx = {
            particles: new ParticleSystem(this.scene, 500),
            shake: new CameraShake(),
            hitStop: new HitStop(),
            trails: new MotionTrails(),
            shockwaves: new ShockwaveRings(this.scene),
            floatingText: new FloatingText()
        };

        // Initialize pools
        this.enemyPool = new ObjectPool(() => {
            const enemy = new Enemy(
                this,
                new THREE.Vector3(0, 0, 0)
            );
            return enemy;
        }, 60);

        this.bulletPool = new ObjectPool(() => {
            const bullet = new Bullet(
                this,
                new THREE.Vector3(0, 0, 0)
            );
            return bullet;
        }, 50);

        this.powerupPool = new ObjectPool(() => {
            const powerup = new Powerup(this);
            return powerup;
        }, 10);

        // Setup lighting
        const ambientLight = new THREE.AmbientLight(0x404080, 0.5);
        this.scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(10, 20, 10);
        this.scene.add(directionalLight);

        // Setup stars background
        this.setupStars();

        // Event listeners
        window.addEventListener('resize', () => this.onResize());

        // Hide loading screen
        setTimeout(() => {
            document.getElementById('loading')!.style.display = 'none';
        }, 500);

        // Start game loop
        this.lastTime = performance.now();
    }

    private setupStars(): void {
        const starGeometry = new THREE.BufferGeometry();
        const starCount = 1000;
        const positions = new Float32Array(starCount * 3);
        const colors = new Float32Array(starCount * 3);

        for (let i = 0; i < starCount; i++) {
            const i3 = i * 3;

            // Random position in a large sphere
            positions[i3] = (Math.random() - 0.5) * 200;
            positions[i3 + 1] = (Math.random() - 0.5) * 200;
            positions[i3 + 2] = (Math.random() - 0.5) * 200;

            // Random color with slight blue tint
            const brightness = Math.random();
            colors[i3] = brightness * 0.8 + 0.2;
            colors[i3 + 1] = brightness * 0.8 + 0.2;
            colors[i3 + 2] = brightness * 1.0 + 0.5;
        }

        starGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        starGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const starMaterial = new THREE.PointsMaterial({
            size: 0.5,
            vertexColors: true,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });

        const stars = new THREE.Points(starGeometry, starMaterial);
        this.scene.add(stars);
    }

    public start(): void {
        this.resetGame();
        this.gameState = 'playing';

        document.getElementById('main-menu')!.classList.add('hidden');
        document.getElementById('game-over')!.classList.add('hidden');

        // Initialize audio context on user interaction
        if (!this.audioContext) {
            this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        }

        this.spawnWave();
    }

    public restart(): void {
        this.start();
    }

    public showHighScore(): void {
        alert(`High Score: ${this.highScore}`);
    }

    private resetGame(): void {
        // Clear existing entities
        if (this.player) {
            this.scene.remove(this.player.mesh);
            this.player.dispose();
        }

        this.enemies.forEach(e => this.scene.remove(e.mesh));
        this.bullets.forEach(b => this.scene.remove(b.mesh));
        this.powerups.forEach(p => this.scene.remove(p.mesh));

        this.enemies = [];
        this.bullets = [];
        this.powerups = [];

        // Reset pools
        this.enemyPool.reset();
        this.bulletPool.reset();
        this.powerupPool.reset();

        // Reset game state
        this.waveNumber = 1;
        this.lives = 3;
        this.score = 0;
        this.formationDirection = 1;

        this.updateHUD();
    }

    private spawnWave(): void {
        // Generate enemy formation based on wave number
        const initialCount = this.ENEMY_ROW_COUNT * this.ENEMY_COL_COUNT;
        const aliveCount = this.enemies.filter(e => e.active).length;

        // Calculate current speed (increases with difficulty)
        const difficultyMultiplier = 1 + (this.waveNumber - 1) * 0.1;
        this.formationSpeed = 20 * difficultyMultiplier;

        // Spawn enemies in grid formation
        for (let row = 0; row < this.ENEMY_ROW_COUNT; row++) {
            for (let col = 0; col < this.ENEMY_COL_COUNT; col++) {
                const position = new THREE.Vector3(
                    -15 + col * this.ENEMY_SPACING_X,
                    20 - row * this.ENEMY_SPACING_Y,
                    0
                );

                // Determine enemy type based on row and wave
                let type: EnemyType = EnemyType.GRUNT;
                if (this.waveNumber >= 3 && row === 0) {
                    type = Math.random() < 0.3 ? EnemyType.ELITE : EnemyType.GRUNT;
                } else if (this.waveNumber % 3 === 0 && row === 0 && col === 5) {
                    // Spawn boss every 3rd wave at center top
                    const boss = new Boss(this.enemyPool, position);
                    this.enemies.push(boss);
                    continue;
                }

                const enemy = this.enemyPool.get();
                if (enemy) {
                    enemy.initialize(position, type, this.waveNumber);
                    this.enemies.push(enemy);
                }
            }
        }

        this.updateHUD();
    }

    private updateFormation(deltaTime: number): void {
        const activeEnemies = this.enemies.filter(e => e.active && !e.isBoss);

        if (activeEnemies.length === 0) return;

        // Check edge boundaries
        let hitEdge = false;
        for (const enemy of activeEnemies) {
            if ((this.formationDirection > 0 && enemy.position.x > this.SCREEN_WIDTH / 2 - 2) ||
                (this.formationDirection < 0 && enemy.position.x < -this.SCREEN_WIDTH / 2 + 2)) {
                hitEdge = true;
                break;
            }
        }

        if (hitEdge) {
            this.formationDirection *= -1;

            // Drop all enemies down
            for (const enemy of activeEnemies) {
                enemy.position.y -= this.formationDropDistance;

                // Game over if enemies reach player line
                if (enemy.position.y < this.PLAYER_Y + 5) {
                    this.triggerGameOver();
                    return;
                }
            }

            // Increase speed slightly on each drop
            this.formationSpeed *= 1.02;
        } else {
            // Move formation horizontally
            for (const enemy of activeEnemies) {
                enemy.position.x += this.formationDirection * this.formationSpeed * deltaTime;
            }
        }
    }

    private updatePlayer(deltaTime: number): void {
        if (!this.player || !this.player.active) return;

        const moveSpeed = 30;
        let velocityX = 0;

        // Keyboard input
        if (this.input.isKeyDown('ArrowLeft') || this.input.isKeyDown('a')) {
            velocityX -= moveSpeed;
        }
        if (this.input.isKeyDown('ArrowRight') || this.input.isKeyDown('d')) {
            velocityX += moveSpeed;
        }

        // Gamepad input
        const gamepad = this.input.getGamepad();
        if (gamepad) {
            const axisValue = gamepad.axes[0];
            if (Math.abs(axisValue) > 0.15) {
                velocityX = axisValue * moveSpeed;
            }
        }

        // Apply movement with boundary constraints
        this.player.position.x += velocityX * deltaTime;
        this.player.position.x = Math.max(-this.SCREEN_WIDTH / 2 + 2, 
                                          Math.min(this.SCREEN_WIDTH / 2 - 2, 
                                                  this.player.position.x));

        // Shooting input
        if (this.input.isKeyDown('Space') || this.input.isGamepadButtonPressed(0)) {
            this.fireBullet();
        }
    }

    private fireBullet(): void {
        if (!this.player || !this.player.active) return;

        const bullet = this.bulletPool.get();
        if (bullet && bullet instanceof Bullet) {
            bullet.initialize(this.player.position.clone(), -200, 'player');
            this.bullets.push(bullet);

            // Play shoot sound
            this.playShootSound();
        }
    }

    private updateBullets(deltaTime: number): void {
        for (const bullet of this.bullets) {
            if (!bullet.active) continue;

            bullet.position.y += bullet.velocity.y * deltaTime;

            // Remove bullets off screen
            if (bullet.position.y < -30 || bullet.position.y > 30) {
                bullet.deactivate();
            }
        }

        // Cleanup inactive bullets from array
        this.bullets = this.bullets.filter(b => b.active);
    }

    private updateEnemies(deltaTime: number): void {
        for (const enemy of this.enemies) {
            if (!enemy.active) continue;

            enemy.update(deltaTime);

            // Enemy shooting logic
            if (Math.random() < 0.01 * this.waveNumber && !enemy.isBoss) {
                const bullet = this.bulletPool.get();
                if (bullet && bullet instanceof Bullet) {
                    bullet.initialize(enemy.position.clone(), -150, 'enemy');
                    this.bullets.push(bullet);
                }
            }

            // Boss shooting handled in Boss class
        }
    }

    private checkCollisions(): void {
        const activeBullets = this.bullets.filter(b => b.active);
        const activeEnemies = this.enemies.filter(e => e.active && !e.isBoss);

        // Bullet vs Enemy collisions
        for (const bullet of activeBullets) {
            if (!bullet.active || bullet.ownerType !== 'player') continue;

            for (const enemy of activeEnemies) {
                if (!enemy.active) continue;

                const bulletBox = new THREE.Box3().setFromObject(bullet.mesh);
                const enemyBox = new THREE.Box3().setFromObject(enemy.mesh);

                if (bulletBox.intersectsBox(enemyBox)) {
                    // Hit enemy
                    bullet.deactivate();
                    this.damageEnemy(enemy, 10);

                    // Particle effect
                    this.vfx.particles.spawnExplosion(
                        bullet.position.clone(),
                        5,
                        new THREE.Color('#ff0')
                    );

                    break;
                }
            }
        }

        // Bullet vs Boss collision
        const boss = this.enemies.find(e => e.isBoss);
        if (boss && boss.active) {
            for (const bullet of activeBullets) {
                if (!bullet.active || bullet.ownerType !== 'player') continue;

                const bulletBox = new THREE.Box3().setFromObject(bullet.mesh);
                const bossBox = new THREE.Box3().setFromObject(boss.mesh);

                if (bulletBox.intersectsBox(bossBox)) {
                    bullet.deactivate();
                    this.damageEnemy(boss, 10);

                    this.vfx.particles.spawnExplosion(
                        bullet.position.clone(),
                        5,
                        new THREE.Color('#ffd700')
                    );

                    break;
                }
            }
        }

        // Enemy Bullet vs Player collision
        const playerBullet = activeBullets.find(b => b.active && b.ownerType === 'enemy');
        if (playerBullet && this.player?.active) {
            const bulletBox = new THREE.Box3().setFromObject(playerBullet.mesh);
            const playerBox = new THREE.Box3().setFromObject(this.player.mesh);

            if (bulletBox.intersectsBox(playerBox)) {
                playerBullet.deactivate();
                this.damagePlayer(10);
            }
        }

        // Enemy vs Player collision (crash)
        for (const enemy of activeEnemies) {
            if (!enemy.active) continue;

            const enemyBox = new THREE.Box3().setFromObject(enemy.mesh);
            const playerBox = new THREE.Box3().setFromObject(this.player!.mesh);

            if (enemyBox.intersectsBox(playerBox)) {
                this.damagePlayer(20);
                enemy.deactivate();

                this.vfx.particles.spawnExplosion(
                    enemy.position.clone(),
                    15,
                    new THREE.Color('#f00')
                );
            }
        }

        // Powerup collection
        for (const powerup of this.powerups) {
            if (!powerup.active) continue;

            const powerupBox = new THREE.Box3().setFromObject(powerup.mesh);
            const playerBox = new THREE.Box3().setFromObject(this.player!.mesh);

            if (powerupBox.intersectsBox(playerBox)) {
                this.activatePowerup(powerup.type);
                powerup.deactivate();
            }
        }
    }

    private damageEnemy(enemy: Enemy, damage: number): void {
        enemy.health -= damage;

        // Score calculation based on enemy type
        const baseScore = enemy.scoreValue;
        this.score += baseScore;

        // Combo system
        if (this.score.comboTimer > 0) {
            this.score.comboCount++;
            this.score.comboMultiplier = Math.min(5, 1 + this.score.comboCount * 0.2);
        } else {
            this.score.comboCount = 1;
            this.score.comboMultiplier = 1;
        }

        this.score.comboTimer = 3.0; // 3 second combo window

        const finalScore = Math.floor(baseScore * this.score.comboMultiplier);
        this.score.update(finalScore, enemy.position.clone());

        if (enemy.health <= 0) {
            this.killEnemy(enemy);
        }
    }

    private killEnemy(enemy: Enemy): void {
        enemy.deactivate();

        // Explosion effect
        this.vfx.particles.spawnExplosion(
            enemy.position.clone(),
            15,
            new THREE.Color(enemy.type === EnemyType.BOSS ? '#ffd700' : 
                          enemy.type === EnemyType.ELITE ? '#f0f' : '#0f0')
        );

        // Shockwave on boss death
        if (enemy.isBoss) {
            this.vfx.shockwaves.spawn(enemy.position.clone(), 3);
            this.vfx.hitStop.trigger(0.2);
        } else {
            // Chance to drop powerup
            if (Math.random() < 0.05) {
                const powerup = this.powerupPool.get();
                if (powerup) {
                    powerup.initialize(enemy.position.clone());
                    this.powerups.push(powerup);
                }
            }
        }

        // Check wave completion
        const remainingEnemies = this.enemies.filter(e => e.active && !e.isBoss).length;
        const bossAlive = this.enemies.some(e => e.isBoss && e.active);

        if (remainingEnemies === 0 && !bossAlive) {
            this.completeWave();
        }
    }

    private damagePlayer(damage: number): void {
        if (!this.player || !this.player.active) return;

        this.lives -= Math.floor(damage / 10);

        // Camera shake and hit stop
        this.vfx.shake.trigger(2.0);
        this.vfx.hitStop.trigger(0.3);

        // Explosion effect at player position
        this.vfx.particles.spawnExplosion(
            this.player.position.clone(),
            20,
            new THREE.Color('#f00')
        );

        if (this.lives <= 0) {
            this.triggerGameOver();
        } else {
            // Respawn player with invulnerability
            this.player.respawn();
            this.updateHUD();
        }
    }

    private activatePowerup(type: PowerupType): void {
        const indicator = document.getElementById('powerup-indicator')!;

        switch (type) {
            case PowerupType.SPREAD_SHOT:
                this.player!.activateSpreadShot(10);
                indicator.textContent = 'SPREAD SHOT';
                break;
            case PowerupType.RAPID_FIRE:
                this.player!.activateRapidFire(8);
                indicator.textContent = 'RAPID FIRE';
                break;
            case PowerupType.EXTRA_LIFE:
                this.lives = Math.min(5, this.lives + 1);
                indicator.textContent = '+1 LIFE';
                break;
            case PowerupType.SHIELD_BOOST:
                // Shield regeneration handled in Player class
                indicator.textContent = 'SHIELD BOOST';
                break;
        }

        indicator.classList.add('active');
        setTimeout(() => {
            indicator.classList.remove('active');
        }, 2000);

        this.playPowerupSound();
    }

    private completeWave(): void {
        // Clear remaining enemies
        for (const enemy of this.enemies) {
            if (enemy.active) {
                enemy.deactivate();
                this.vfx.particles.spawnExplosion(
                    enemy.position.clone(),
                    10,
                    new THREE.Color('#0ff')
                );
            }
        }

        // Bonus score for wave completion
        const bonus = this.waveNumber * 100;
        this.score.update(bonus, new THREE.Vector3(0, 10, 0));

        // Increase wave number
        this.waveNumber++;

        if (this.waveNumber > 10) {
            // Victory condition
            this.triggerVictory();
        } else {
            // Spawn next wave after delay
            setTimeout(() => {
                this.spawnWave();
            }, 3000);
        }
    }

    private triggerGameOver(): void {
        this.gameState = 'gameover';

        if (this.score > this.highScore) {
            this.highScore = Math.floor(this.score);
            localStorage.setItem('spaceInvadersHighScore', this.highScore.toString());
        }

        document.getElementById('final-score')!.textContent = Math.floor(this.score).toString();
        document.getElementById('game-over')!.classList.remove('hidden');

        // Massive explosion at player position
        if (this.player) {
            this.vfx.particles.spawnExplosion(
                this.player.position.clone(),
                50,
                new THREE.Color('#f00')
            );
        }

        this.updateHUD();
    }

    private triggerVictory(): void {
        this.gameState = 'victory';

        // Victory celebration
        for (let i = 0; i < 5; i++) {
            setTimeout(() => {
                const position = new THREE.Vector3(
                    (Math.random() - 0.5) * 40,
                    (Math.random() - 0.5) * 20,
                    0
                );
                this.vfx.particles.spawnExplosion(position, 30, new THREE.Color('#ffd700'));
            }, i * 500);
        }

        setTimeout(() => {
            document.getElementById('game-over')!.classList.remove('hidden');
            document.querySelector('.gameover-text')!.textContent = 'VICTORY!';
            document.querySelector('.final-score')!.innerHTML = `Final Score: ${Math.floor(this.score)}`;
        }, 5000);
    }

    private updateHUD(): void {
        document.getElementById('score-display')!.textContent = Math.floor(this.score).toString();
        document.getElementById('high-score-display')!.textContent = this.highScore.toString();
        document.getElementById('wave-display')!.textContent = this.waveNumber.toString();
        document.getElementById('lives-display')!.textContent = this.lives.toString();

        // Update combo counter
        const comboCounter = document.getElementById('combo-counter')!;
        if (this.score.comboCount > 1) {
            comboCounter.textContent = `x${this.score.comboMultiplier.toFixed(1)}`;
            comboCounter.classList.add('active');
        } else {
            comboCounter.classList.remove('active');
        }
    }

    private playShootSound(): void {
        if (!this.audioContext) return;

        const oscillator = this.audioContext.createOscillator();
        const gainNode = this.audioContext.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(this.audioContext.destination);

        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(800, this.audioContext.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(200, this.audioContext.currentTime + 0.1);

        gainNode.gain.setValueAtTime(0.3, this.audioContext.currentTime);
        gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + 0.1);

        oscillator.start(this.audioContext.currentTime);
        oscillator.stop(this.audioContext.currentTime + 0.1);
    }

    private playPowerupSound(): void {
        if (!this.audioContext) return;

        const now = this.audioContext.currentTime;

        // Arpeggiated sequence
        [261.63, 329.63, 392.00, 523.25].forEach((freq, i) => {
            const oscillator = this.audioContext.createOscillator();
            const gainNode = this.audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(this.audioContext.destination);

            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(freq, now + i * 0.1);

            gainNode.gain.setValueAtTime(0.2, now + i * 0.1);
            gainNode.gain.exponentialRampToValueAtTime(0.01, now + i * 0.1 + 0.3);

            oscillator.start(now + i * 0.1);
            oscillator.stop(now + i * 0.1 + 0.3);
        });
    }

    private onResize(): void {
        this.camera.aspect = window.innerWidth / window.innerHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.composer.setSize(window.innerWidth, window.innerHeight);
    }

    public update(deltaTime: number): void {
        if (this.gameState !== 'playing') return;

        // Update systems
        this.updatePlayer(deltaTime);
        this.updateBullets(deltaTime);
        this.updateEnemies(deltaTime);
        this.updateFormation(deltaTime);

        // Check collisions
        this.checkCollisions();

        // Update VFX systems
        this.vfx.particles.update(deltaTime);
        this.vfx.shake.update(deltaTime, this.camera.position);
        this.vfx.hitStop.update(deltaTime);
        this.vfx.trails.update(deltaTime);
        this.vfx.shockwaves.update(deltaTime);
        this.vfx.floatingText.update(deltaTime);

        // Update combo timer
        if (this.score.comboTimer > 0) {
            this.score.comboTimer -= deltaTime;
            if (this.score.comboTimer <= 0) {
                this.score.comboCount = 0;
                this.score.comboMultiplier = 1;
            }
        }

        // Update powerups
        for (const powerup of this.powerups) {
            if (powerup.active) {
                powerup.update(deltaTime);
            }
        }
        this.powerups = this.powerups.filter(p => p.active);
    }

    public render(): void {
        // Apply camera shake
        const shakeOffset = this.vfx.shake.getShakeOffset();
        this.camera.position.x += shakeOffset.x;
        this.camera.position.y += shakeOffset.y;

        // Render scene with post-processing
        this.composer.render();

        // Reset camera position
        this.camera.position.x -= shakeOffset.x;
        this.camera.position.y -= shakeOffset.y;
    }

    public dispose(): void {
        // Dispose all Three.js resources
        this.memory.disposeGame();

        if (this.player) {
            this.scene.remove(this.player.mesh);
            this.player.dispose();
        }

        this.enemies.forEach(e => {
            this.scene.remove(e.mesh);
            e.dispose();
        });

        this.bullets.forEach(b => {
            this.scene.remove(b.mesh);
            b.dispose();
        });

        this.powerups.forEach(p => {
            this.scene.remove(p.mesh);
            p.dispose();
        });

        // Dispose post-processing
        this.composer.dispose();
        this.renderer.dispose();

        window.removeEventListener('resize', () => this.onResize());
    }
}

import { Powerup, PowerupType } from './Entities/Powerup';
    private type: PowerupType;
    private velocityY: number = -50;
    private lifetime: number = 10; // seconds
    private active: boolean = false;

    constructor(game: Game) {
        const geometry = new THREE.RingGeometry(1, 1.5, 8);
        let color = new THREE.Color();

        switch (game.score.comboCount % 4) {
            case 0: color = new THREE.Color('#f0f'); break; // Spread shot
            case 1: color = new THREE.Color('#ff0'); break; // Rapid fire
            case 2: color = new THREE.Color('#0f0'); break; // Extra life
            case 3: color = new THREE.Color('#0ff'); break; // Shield boost
        }

        const material = new THREE.MeshStandardMaterial({
            color: color,
            emissive: color,
            emissiveIntensity: 2,
            side: THREE.DoubleSide
        });

        super(geometry, material);

        this.type = PowerupType.SPREAD_SHOT; // Default
    }

    public initialize(position: THREE.Vector3): void {
        this.position.copy(position);
        this.active = true;
        this.lifetime = 10;

        // Random power-up type
        this.type = PowerupType[this.score.comboCount % 4] as PowerupType;
    }

    public update(deltaTime: number): void {
        this.position.y += this.velocityY * deltaTime;
        this.lifetime -= deltaTime;

        if (this.lifetime <= 0) {
            this.active = false;
        }
    }

    public deactivate(): void {
        this.active = false;
    }

    public dispose(): void {
        this.geometry.dispose();
        this.material.dispose();
    }
}

import { Vector3, Color } from 'three';
import { ObjectPool } from '../../shared/core/ObjectPool';
import { createEnemyTexture, EnemyType } from '../../shared/utils/ProceduralTextures';

export interface EnemyConfig {
    type: EnemyType;
    position: Vector3;
}

export class Enemy {
    public mesh: THREE.Mesh;
    public position: Vector3 = new Vector3();
    public velocity: Vector3 = new Vector3();
    public health: number = 1;
    public scoreValue: number = 0;
    public isDead: boolean = false;
    public type: EnemyType;

    private static readonly TYPES = {
        grunt: { health: 1, speed: 1.0, score: 30, color: '#00FF00' },
        elite: { health: 2, speed: 1.5, score: 60, color: '#FF00FF' },
        boss: { health: 5, speed: 0.7, score: 150, color: '#FFD700' }
    };

    constructor(config: EnemyConfig) {
        this.type = config.type;
        const typeData = Enemy.TYPES[config.type];

        this.health = typeData.health;
        this.scoreValue = typeData.score;

        // Create procedural texture
        const texture = createEnemyTexture(config.type);
        const material = new THREE.MeshStandardMaterial({
            map: texture,
            emissive: new Color(typeData.color),
            emissiveIntensity: 0.5 + (this.health / typeData.health) * 1.5,
            metalness: 0.6,
            roughness: 0.3
        });

        // Create enemy mesh with retro-futuristic shape
        const geometry = new THREE.BoxGeometry(2, 1.5, 1);
        this.mesh = new THREE.Mesh(geometry, material);

        this.position.copy(config.position);
        this.mesh.position.copy(this.position);
    }

    public update(deltaTime: number, direction: number, baseSpeed: number): void {
        if (this.isDead) return;

        const typeData = Enemy.TYPES[this.type];
        const speedMultiplier = 1 + (0.3 * (55 - this.getAliveCount()) / 55);
        const currentSpeed = baseSpeed * direction * typeData.speed * speedMultiplier * deltaTime;

        this.position.x += currentSpeed;
        this.mesh.position.x = this.position.x;
    }

    public takeDamage(): void {
        this.health--;
        if (this.health <= 0) {
            this.isDead = true;
        } else {
            // Update emissive intensity based on remaining health
            const typeData = Enemy.TYPES[this.type];
            const material = this.mesh.material as THREE.MeshStandardMaterial;
            material.emissiveIntensity = 0.5 + (this.health / typeData.health) * 1.5;
        }
    }

    public getAliveCount(): number {
        // This will be overridden by the game manager
        return 55;
    }

    public dispose(): void {
        this.mesh.geometry.dispose();
        (this.mesh.material as THREE.MeshStandardMaterial).map?.dispose();
        this.mesh.material.dispose();
    }
}

export class EnemyManager {
    private enemies: Enemy[] = [];
    private pool: ObjectPool<Enemy> | null = null;
    public direction: number = 1;
    public baseSpeed: number = 20.0;
    public dropDistance: number = 2.0;

    constructor() {
        this.initializeFormation();
    }

    private initializeFormation(): void {
        const rows = 5;
        const cols = 11;
        const startX = -30;
        const startY = -15;
        const spacingX = 4.5;
        const spacingY = 2.5;

        for (let row = 0; row < rows; row++) {
            for (let col = 0; col < cols; col++) {
                let type: EnemyType = 'grunt';

                // Elite enemies in rows 1-3, columns 2-8
                if (row >= 1 && row <= 3 && col >= 2 && col <= 8) {
                    type = 'elite';
                }

                const position = new Vector3(
                    startX + col * spacingX,
                    startY - row * spacingY,
                    0
                );

                this.enemies.push(new Enemy({
                    type: type,
                    position: position
                }));
            }
        }
    }

    public update(deltaTime: number): void {
        let hitEdge = false;
        const LEFT_BOUNDARY = -30;
        const RIGHT_BOUNDARY = 30;

        // Check if any enemy reached the edge
        for (const enemy of this.enemies) {
            if (!enemy.isDead && 
                (enemy.position.x <= LEFT_BOUNDARY || enemy.position.x >= RIGHT_BOUNDARY)) {
                hitEdge = true;
                break;
            }
        }

        if (hitEdge) {
            // Flip direction and drop down
            this.direction *= -1;

            for (const enemy of this.enemies) {
                if (!enemy.isDead) {
                    enemy.position.y -= this.dropDistance;
                    enemy.mesh.position.y = enemy.position.y;
                }
            }
        }

        // Update all enemies
        for (const enemy of this.enemies) {
            if (!enemy.isDead) {
                enemy.update(deltaTime, this.direction, this.baseSpeed);
            }
        }
    }

    public getAliveCount(): number {
        return this.enemies.filter(e => !e.isDead).length;
    }

    public getAllEnemies(): Enemy[] {
        return this.enemies.filter(e => !e.isDead);
    }

    public reset(): void {
        for (const enemy of this.enemies) {
            enemy.isDead = false;
            const typeData = Enemy.TYPES[enemy.type];
            enemy.health = typeData.health;
        }
        this.direction = 1;
        this.initializeFormation();
    }

    public dispose(): void {
        for (const enemy of this.enemies) {
            enemy.dispose();
        }
        if (this.pool) {
            this.pool.clear();
        }
    }
}

import { Texture, CanvasTexture } from 'three';

export enum EnemyType {
    GRUNT = 'grunt',
    ELITE = 'elite',
    BOSS = 'boss'
}

export function createEnemyTexture(type: EnemyType): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 128;
    const ctx = canvas.getContext('2d')!;

    // Clear background
    ctx.clearRect(0, 0, 128, 128);

    if (type === EnemyType.GRUNT) {
        ctx.fillStyle = '#00FF00';
        // Body
        ctx.fillRect(32, 48, 64, 32);
        // Top section
        ctx.fillRect(16, 32, 96, 16);
        // Arms
        ctx.fillRect(8, 48, 16, 24);
        ctx.fillRect(104, 48, 16, 24);
        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(40, 52, 16, 8);
        ctx.fillRect(72, 52, 16, 8);
    } else if (type === EnemyType.ELITE) {
        ctx.fillStyle = '#FF00FF';
        // Elite has more complex shape
        ctx.beginPath();
        ctx.moveTo(32, 48);
        ctx.lineTo(96, 48);
        ctx.lineTo(112, 72);
        ctx.lineTo(16, 72);
        ctx.closePath();
        ctx.fill();
        // Top detail
        ctx.fillRect(40, 32, 48, 16);
        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(48, 56, 12, 8);
        ctx.fillRect(68, 56, 12, 8);
    } else if (type === EnemyType.BOSS) {
        ctx.fillStyle = '#FFD700';
        // Boss is large and imposing
        ctx.beginPath();
        ctx.moveTo(16, 48);
        ctx.lineTo(112, 48);
        ctx.lineTo(128, 96);
        ctx.lineTo(0, 96);
        ctx.closePath();
        ctx.fill();
        // Core detail
        ctx.fillStyle = '#FFA500';
        ctx.fillRect(48, 56, 32, 24);
        // Eyes
        ctx.fillStyle = '#000';
        ctx.fillRect(32, 64, 16, 12);
        ctx.fillRect(80, 64, 16, 12);
    }

    return canvas;
}

export function createShieldTexture(): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 128;
    const ctx = canvas.getContext('2d')!;

    // Shield dome shape
    ctx.fillStyle = '#00FFFF';
    ctx.beginPath();
    ctx.arc(64, 96, 50, Math.PI, 0);
    ctx.fill();

    // Grid pattern for retro feel
    ctx.strokeStyle = '#0088FF';
    ctx.lineWidth = 2;
    for (let i = 0; i < 10; i++) {
        ctx.beginPath();
        ctx.moveTo(64 + (i - 5) * 8, 96);
        ctx.lineTo(64 + (i - 5) * 8, 128);
        ctx.stroke();
    }

    return canvas;
}

export function createPowerUpTexture(type: string): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 64;
    const ctx = canvas.getContext('2d')!;

    if (type === 'spread') {
        ctx.fillStyle = '#FF00FF';
        ctx.beginPath();
        for (let i = 0; i < 5; i++) {
            const angle = (i * 72 - 90) * Math.PI / 180;
            const x = 32 + Math.cos(angle) * 24;
            const y = 32 + Math.sin(angle) * 24;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fill();
    } else if (type === 'rapid') {
        ctx.fillStyle = '#FFA500';
        ctx.fillRect(16, 16, 32, 32);
        ctx.strokeStyle = '#FFF';
        ctx.lineWidth = 4;
        ctx.strokeRect(20, 20, 24, 24);
    } else if (type === 'life') {
        ctx.fillStyle = '#00FF00';
        ctx.beginPath();
        ctx.moveTo(32, 16);
        ctx.bezierCurveTo(48, 16, 56, 32, 56, 40);
        ctx.bezierCurveTo(56, 56, 32, 64, 32, 64);
        ctx.bezierCurveTo(32, 64, 8, 56, 8, 40);
        ctx.bezierCurveTo(8, 32, 16, 16, 32, 16);
        ctx.fill();
    } else if (type === 'shield') {
        ctx.fillStyle = '#00FFFF';
        ctx.beginPath();
        ctx.arc(32, 32, 24, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#FFF';
        ctx.lineWidth = 4;
        ctx.stroke();
    }

    return canvas;
}

export function createStarTexture(): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const ctx = canvas.getContext('2d')!;

    // Random star shape
    const points = Math.floor(Math.random() * 3) + 4;
    const outerRadius = 10;
    const innerRadius = 5;
    const cx = 16;
    const cy = 16;

    ctx.fillStyle = '#FFF';
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
        const angle = (i * Math.PI) / points - Math.PI / 2;
        const radius = i % 2 === 0 ? outerRadius : innerRadius;
        const x = cx + Math.cos(angle) * radius;
        const y = cy + Math.sin(angle) * radius;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();

    return canvas;
}

export function createBackgroundTexture(): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d')!;

    // Deep space gradient
    const gradient = ctx.createLinearGradient(0, 0, 0, 512);
    gradient.addColorStop(0, '#000011');
    gradient.addColorStop(0.5, '#000033');
    gradient.addColorStop(1, '#000011');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 512, 512);

    // Random stars
    for (let i = 0; i < 200; i++) {
        const x = Math.random() * 512;
        const y = Math.random() * 512;
        const size = Math.random() * 2 + 1;
        const alpha = Math.random() * 0.8 + 0.2;

        ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
        ctx.beginPath();
        ctx.arc(x, y, size, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
}

import * as THREE from 'three';

export class MemoryManager {
    private trackedResources: Set<THREE.Object3D | THREE.Material | THREE.Geometry | THREE.Texture> = new Set();

    public track(resource: THREE.Object3D | THREE.Material | THREE.Geometry | THREE.Texture): void {
        this.trackedResources.add(resource);
    }

    public disposeResource(resource: THREE.Object3D | THREE.Material | THREE.Geometry | THREE.Texture): void {
        if (resource instanceof THREE.Object3D) {
            resource.traverse((child) => {
                if ((child as THREE.Mesh).geometry) {
                    const geom = (child as THREE.Mesh).geometry;
                    this.disposeGeometry(geom);
                }
                if ((child as THREE.Mesh).material) {
                    const mat = (child as THREE.Mesh).material;
                    this.disposeMaterial(mat);
                }
            });
        } else if (resource instanceof THREE.Material) {
            this.disposeMaterial(resource);
        } else if (resource instanceof THREE.Geometry || resource instanceof THREE.BufferGeometry) {
            this.disposeGeometry(resource);
        } else if (resource instanceof THREE.Texture) {
            this.disposeTexture(resource);
        }
        this.trackedResources.delete(resource);
    }

    private disposeMaterial(material: THREE.Material): void {
        material.dispose();
        const mat = material as THREE.Material & { [key: string]: any };
        for (const key in mat) {
            if (mat.hasOwnProperty(key)) {
                const value = mat[key];
                if (value instanceof THREE.Texture) {
                    this.disposeTexture(value);
                }
            }
        }
    }

    private disposeGeometry(geometry: THREE.Geometry | THREE.BufferGeometry): void {
        geometry.dispose();
    }

    private disposeTexture(texture: THREE.Texture): void {
        texture.dispose();
        if (texture.map) this.disposeTexture(texture.map);
        if (texture.envMap) this.disposeTexture(texture.envMap);
        if (texture.displacementMap) this.disposeTexture(texture.displacementMap);
    }

    public disposeAll(): void {
        for (const resource of this.trackedResources) {
            this.disposeResource(resource);
        }
        this.trackedResources.clear();
    }

    public getTrackedCount(): number {
        return this.trackedResources.size;
    }
}

import * as THREE from 'three';
import { FontLoader } from 'three/examples/jsm/loaders/FontLoader.js';

export class FloatingText {
    private texts: FloatingTextItem[] = [];
    private font: THREE.Font | null = null;
    private loader: FontLoader;

    constructor() {
        this.loader = new FontLoader();
        this.loadRetroFont();
    }

    private loadRetroFont(): void {
        // Load a standard font from Three.js examples CDN
        this.loader.load(
            'https://threejs.org/examples/fonts/helvetiker_bold.typeface.json',
            (font) => {
                this.font = font;
            },
            undefined,
            (err) => {
                console.error('Font loading error:', err);
            }
        );
    }

    public spawn(position: THREE.Vector3, text: string, color: string, size: number = 1): void {
        if (!this.font) return;

        const geometry = new THREE.TextGeometry(text, {
            font: this.font,
            size: size * 2,
            height: 0.5,
            curveSegments: 4,
            bevelEnabled: true,
            bevelThickness: 0.1,
            bevelSize: 0.05,
            bevelOffset: 0,
            bevelSegments: 2
        });

        geometry.center();

        const material = new THREE.MeshBasicMaterial({ 
            color: color,
            transparent: true,
            opacity: 1.0
        });

        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.copy(position);

        // Add slight random rotation for variety
        mesh.rotation.x = Math.random() * 0.2;
        mesh.rotation.y = Math.random() * 0.2;

        const item: FloatingTextItem = {
            mesh: mesh,
            velocity: new THREE.Vector3(0, 150, 0), // Float upward
            lifetime: 2.0,
            maxLifetime: 2.0,
            color: color
        };

        this.texts.push(item);
    }

    public update(deltaTime: number): void {
        for (let i = this.texts.length - 1; i >= 0; i--) {
            const item = this.texts[i];

            // Update lifetime
            item.lifetime -= deltaTime;

            if (item.lifetime <= 0) {
                // Cleanup
                item.mesh.geometry.dispose();
                item.mesh.material.dispose();
                this.texts.splice(i, 1);
                continue;
            }

            // Move upward
            item.mesh.position.addScaledVector(item.velocity, deltaTime);

            // Fade out
            const opacity = Math.max(0, item.lifetime / item.maxLifetime);
            item.mesh.material.opacity = opacity;

            // Slight rotation for dynamic effect
            item.mesh.rotation.z += deltaTime * 2;
        }
    }

    public addToScene(scene: THREE.Scene): void {
        this.texts.forEach(item => scene.add(item.mesh));
    }

    public clear(): void {
        this.texts.forEach(item => {
            item.mesh.geometry.dispose();
            item.mesh.material.dispose();
        });
        this.texts = [];
    }
}

interface FloatingTextItem {
    mesh: THREE.Mesh;
    velocity: THREE.Vector3;
    lifetime: number;
    maxLifetime: number;
    color: string;
}

import { Vector3, Color, LineSegments, BufferGeometry, Float32BufferAttribute } from 'three';

export interface TrailPoint {
    position: Vector3;
    color: Color;
    time: number;
}

export class MotionTrail {
    private points: TrailPoint[] = [];
    private maxPoints: number = 10;
    private trailMesh: LineSegments | null = null;
    private geometry: BufferGeometry | null = null;
    private colors: Float32BufferAttribute | null = null;

    constructor(private color: Color, private speedThreshold: number = 100) {
        this.geometry = new BufferGeometry();
        this.colors = new Float32BufferAttribute(new Array(0), 3);
        this.geometry.setAttribute('color', this.colors);
        this.trailMesh = new LineSegments(this.geometry, null); // Material set later
    }

    public addPoint(position: Vector3): void {
        if (this.points.length >= this.maxPoints) {
            this.points.shift();
        }
        this.points.push({
            position: position.clone(),
            color: this.color.clone(),
            time: performance.now()
        });
    }

    public update(): boolean {
        const now = performance.now();

        // Remove old points (older than 1.5 seconds)
        this.points = this.points.filter(p => now - p.time < 1500);

        if (this.points.length < 2) {
            return false;
        }

        // Update geometry
        const positions: number[] = [];
        const colorArray = new Float32Array(this.points.length * 6); // 2 vertices per segment, 3 components each

        for (let i = 0; i < this.points.length - 1; i++) {
            const p1 = this.points[i];
            const p2 = this.points[i + 1];

            positions.push(
                p1.position.x, p1.position.y, p1.position.z,
                p2.position.x, p2.position.y, p2.position.z
            );

            // Fade opacity based on age
            const ageRatio = (now - p1.time) / 1500;
            const alpha = Math.max(0, 1 - ageRatio * 1.5);

            colorArray[i * 6] = p1.color.r * alpha;
            colorArray[i * 6 + 1] = p1.color.g * alpha;
            colorArray[i * 6 + 2] = p1.color.b * alpha;
            colorArray[i * 6 + 3] = p2.color.r * alpha;
            colorArray[i * 6 + 4] = p2.color.g * alpha;
            colorArray[i * 6 + 5] = p2.color.b * alpha;
        }

        this.geometry!.setAttribute('position', new Float32BufferAttribute(positions, 3));
        if (this.colors) {
            this.colors.count = colorArray.length / 3;
            this.colors.array.set(colorArray);
        }

        return true;
    }

    public dispose(): void {
        if (this.geometry) {
            this.geometry.dispose();
            this.geometry = null;
        }
        if (this.trailMesh) {
            // Material disposal handled by caller
            this.trailMesh = null;
        }
        this.points = [];
    }

    public getTrailMesh(): LineSegments | null {
        return this.trailMesh;
    }
}

export class MotionTrailsManager {
    private trails: Map<string, MotionTrail> = new Map();
    private scene: THREE.Scene;

    constructor(scene: THREE.Scene) {
        this.scene = scene;
    }

    public createTrail(id: string, color: Color): void {
        if (!this.trails.has(id)) {
            const trail = new MotionTrail(color);
            this.trails.set(id, trail);

            // Create mesh with proper material
            const material = new THREE.LineBasicMaterial({
                vertexColors: true,
                transparent: true,
                opacity: 0.8
            });
            trail.getTrailMesh()?.setMaterial(material);
            this.scene.add(trail.getTrailMesh()!);
        }
    }

    public addPoint(id: string, position: Vector3): void {
        const trail = this.trails.get(id);
        if (trail) {
            trail.addPoint(position);
        }
    }

    public updateAll(): void {
        for (const [id, trail] of this.trails.entries()) {
            if (!trail.update()) {
                // Remove from scene if no points
                const mesh = trail.getTrailMesh();
                if (mesh) {
                    this.scene.remove(mesh);
                    trail.dispose();
                    this.trails.delete(id);
                }
            }
        }
    }

    public dispose(): void {
        for (const trail of this.trails.values()) {
            const mesh = trail.getTrailMesh();
            if (mesh) {
                this.scene.remove(mesh);
            }
            trail.dispose();
        }
        this.trails.clear();
    }
}

import * as THREE from 'three';
import { FontLoader, TextGeometry } from 'three/examples/jsm/loaders/FontLoader.js';

export class FloatingText {
    private texts: FloatingTextItem[] = [];
    private font: THREE.Font | null = null;
    private loader: FontLoader;

    constructor() {
        this.loader = new FontLoader();
        this.loadRetroFont();
    }

    private loadRetroFont(): void {
        // Load a standard font from Three.js examples CDN
        this.loader.load(
            'https://threejs.org/examples/fonts/helvetiker_bold.typeface.json',
            (font) => {
                this.font = font;
            },
            undefined,
            (err) => {
                console.error('Font loading error:', err);
            }
        );
    }

    public spawn(position: THREE.Vector3, text: string, color: string, size: number = 1): void {
        if (!this.font) return;

        const geometry = new THREE.TextGeometry(text, {
            font: this.font,
            size: size * 2,
            height: 0.5,
            curveSegments: 4,
            bevelEnabled: true,
            bevelThickness: 0.1,
            bevelSize: 0.05,
            bevelOffset: 0,
            bevelSegments: 2
        });

        geometry.center();

        const material = new THREE.MeshBasicMaterial({ 
            color: color,
            transparent: true,
            opacity: 1.0
        });

        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.copy(position);

        // Add slight random rotation for variety
        mesh.rotation.x = Math.random() * 0.2;
        mesh.rotation.y = Math.random() * 0.2;

        const item: FloatingTextItem = {
            mesh: mesh,
            velocity: new THREE.Vector3(0, 150, 0), // Float upward
            lifetime: 2.0,
            maxLifetime: 2.0,
            color: color
        };

        this.texts.push(item);
    }

    public update(deltaTime: number): void {
        for (let i = this.texts.length - 1; i >= 0; i--) {
            const item = this.texts[i];

            // Update lifetime
            item.lifetime -= deltaTime;

            if (item.lifetime <= 0) {
                // Cleanup
                item.mesh.geometry.dispose();
                item.mesh.material.dispose();
                this.texts.splice(i, 1);
                continue;
            }

            // Move upward
            item.mesh.position.addScaledVector(item.velocity, deltaTime);

            // Fade out
            const opacity = Math.max(0, item.lifetime / item.maxLifetime);
            item.mesh.material.opacity = opacity;

            // Slight rotation for dynamic effect
            item.mesh.rotation.z += deltaTime * 2;
        }
    }

    public addToScene(scene: THREE.Scene): void {
        this.texts.forEach(item => scene.add(item.mesh));
    }

    public clear(): void {
        this.texts.forEach(item => {
            item.mesh.geometry.dispose();
            item.mesh.material.dispose();
        });
        this.texts = [];
    }
}

interface FloatingTextItem {
    mesh: THREE.Mesh;
    velocity: THREE.Vector3;
    lifetime: number;
    maxLifetime: number;
    color: string;
}

import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';

export class BloomPipeline {
    private composer: EffectComposer | null = null;
    private bloomPass: UnrealBloomPass | null = null;

    constructor(renderer: THREE.WebGLRenderer, scene: THREE.Scene, camera: THREE.Camera) {
        this.composer = new EffectComposer(renderer);
        this.composer.addPass(new RenderPass(scene, camera));

        // Tuned for retro-futurism: intense but not washed out
        this.bloomPass = new UnrealBloomPass(
            new THREE.Vector2(window.innerWidth, window.innerHeight),
            1.5,   // strength - intense glow
            0.4,   // radius - soft spread
            0.15   // threshold - only bright emissive surfaces trigger
        );

        this.composer.addPass(this.bloomPass);
    }

    public render(deltaTime: number): void {
        if (this.composer) {
            this.composer.render();
        }
    }

    public resize(width: number, height: number): void {
        if (this.composer) {
            this.composer.setSize(width, height);
            if (this.bloomPass) {
                this.bloomPass.resolution.set(width, height);
            }
        }
    }

    public setBloomStrength(strength: number): void {
        if (this.bloomPass) {
            this.bloomPass.strength = strength;
        }
    }

    public getBloomStrength(): number {
        return this.bloomPass ? this.bloomPass.strength : 1.5;
    }

    public dispose(): void {
        if (this.composer) {
            this.composer.dispose();
            this.composer = null;
        }
        if (this.bloomPass) {
            this.bloomPass.dispose();
            this.bloomPass = null;
        }
    }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

import { GameLoop } from '../shared/core/GameLoop';
import { InputManager } from '../shared/core/InputManager';
import { ObjectPool } from '../shared/core/ObjectPool';
import { MemoryManager } from '../shared/core/MemoryManager';

import { ParticleSystem } from '../shared/vfx/ParticleSystem';
import { CameraShake } from '../shared/vfx/CameraShake';
import { HitStop } from '../shared/vfx/HitStop';
import { MotionTrailsManager, Color } from '../shared/vfx/MotionTrails';
import { ShockwaveRings } from '../shared/vfx/ShockwaveRings';
import { FloatingText } from '../shared/vfx/FloatingText';

import { createEnemyTexture, createPlayerTexture, createShieldTexture } from '../shared/utils/ProceduralTextures';
import { Vector3, Color, Scene, Camera, WebGLRenderer } from 'three';

import { Player } from './Entities/Player';
import { Enemy, EnemyType } from './Enemies/Enemy';
import { Boss } from './Enemies/Boss';
import { Bullet } from './Projectiles/Bullet';

import { CollisionSystem } from './Systems/CollisionSystem';
import { ScoreSystem } from './Systems/ScoreSystem';

// Import post-processing setup
import { BloomPipeline } from './PostProcessing';

class SpaceInvadersGame extends GameLoop {
    // Core systems
    private input: InputManager;
    private memory: MemoryManager;

    // VFX Systems
    public vfx: {
        particles: ParticleSystem;
        shake: CameraShake;
        hitStop: HitStop;
        trails: MotionTrails;
        shockwaves: ShockwaveRings;
        floatingTexts: FloatingText;
    };

    // Game entities
    private player: Player | null = null;
    private enemies: Enemy[] = [];
    private bullets: Bullet[] = [];
    private boss: Boss | null = null;

    // Game state
    private score: number = 0;
    private highScore: number = parseInt(localStorage.getItem('spaceInvadersHighScore') || '0');
    private wave: number = 1;
    private lives: number = 3;
    private comboCount: number = 0;
    private comboTimer: number = 0;
    private isPlaying: boolean = false;
    private isGameOver: boolean = false;

    // Scene and rendering
    private scene: THREE.Scene;
    private camera: THREE.Camera;
    private renderer: WebGLRenderer;
    private composer: EffectComposer | null = null;

    // Configuration constants
    private readonly PLAYER_SPEED = 400;
    private readonly BULLET_SPEED = -500;
    private readonly ENEMY_DROP_DISTANCE = 15;
    private readonly SHOOT_COOLDOWN = 0.3;

    constructor() {
        super();

        this.input = new InputManager();
        this.memory = new MemoryManager();

        // Initialize VFX systems
        this.vfx = {
            particles: new ParticleSystem(500), // Hard cap of 500 particles
            shake: new CameraShake(),
            hitStop: new HitStop(),
            trails: new MotionTrails(),
            shockwaves: new ShockwaveRings(),
            floatingTexts: new FloatingText()
        };

        // Initialize scene
        this.initScene();

        // Setup post-processing
        this.composer = initPostProcessing(this.renderer, this.camera);
    }

    private initScene(): void {
        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x050510);

        // Camera setup
        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        this.camera.position.z = 50;

        // Renderer setup
        this.renderer = new THREE.WebGLRenderer({ antialias: false });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.getElementById('game-container')!.appendChild(this.renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404060, 0.5);
        this.scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(10, 20, 10);
        this.scene.add(directionalLight);

        // Background stars (procedural)
        this.createStarfield();
    }

    private createStarfield(): void {
        const starGeometry = new THREE.BufferGeometry();
        const starCount = 500;
        const positions = new Float32Array(starCount * 3);
        const colors = new Float32Array(starCount * 3);

        for (let i = 0; i < starCount; i++) {
            const i3 = i * 3;
            positions[i3] = (Math.random() - 0.5) * 400;
            positions[i3 + 1] = (Math.random() - 0.5) * 200;
            positions[i3 + 2] = Math.random() * 100 - 20;

            const brightness = Math.random();
            colors[i3] = brightness;
            colors[i3 + 1] = brightness;
            colors[i3 + 2] = brightness;
        }

        starGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        starGeometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const starMaterial = new THREE.PointsMaterial({ 
            size: 1.5,
            vertexColors: true,
            transparent: true,
            opacity: 0.8
        });

        const stars = new THREE.Points(starGeometry, starMaterial);
        this.scene.add(stars);

        // Track for disposal later
        this.memory.track(stars);
    }

    public start(): void {
        document.getElementById('main-menu')!.classList.add('hidden');
        document.getElementById('loading')!.style.display = 'none';

        this.resetGame();
        this.isPlaying = true;
        this.isGameOver = false;

        // Start game loop
        this.lastTime = performance.now();
        this.accumulator = 0;
    }

    public restart(): void {
        document.getElementById('game-over')!.classList.add('hidden');
        this.resetGame();
        this.isPlaying = true;
        this.isGameOver = false;
    }

    private resetGame(): void {
        // Clear existing entities
        if (this.player) {
            this.scene.remove(this.player.mesh);
            this.player.dispose();
        }

        this.enemies.forEach(e => this.scene.remove(e.getMesh()));
        this.bullets.forEach(b => this.scene.remove(b.getMesh()));

        this.enemies = [];
        this.bullets = [];
        this.boss = null;

        // Reset state
        this.score = 0;
        this.wave = 1;
        this.lives = 3;
        this.comboCount = 0;
        this.comboTimer = 0;

        this.updateHUD();

        // Create player
        const playerPos = new THREE.Vector3(0, -28, 0);
        this.player = new Player(this.input, playerPos, this.vfx.trails);
        this.scene.add(this.player.getMesh());

        // Spawn enemies for wave 1
        this.spawnWave();
    }

    private spawnWave(): void {
        const rows = 5;
        const cols = 11;
        const spacingX = 6;
        const spacingY = 4;
        const startX = -28;
        const startY = -10;

        for (let row = 0; row < rows; row++) {
            for (let col = 0; col < cols; col++) {
                const pos = new THREE.Vector3(
                    startX + col * spacingX,
                    startY - row * spacingY,
                    0
                );

                // Determine enemy type based on wave and position
                let type: EnemyType = EnemyType.GRUNT;
                if (this.wave >= 3 && row === 0) {
                    type = EnemyType.ELITE;
                }

                const enemy = new Enemy(this.input, pos, type);
                this.enemies.push(enemy);
                this.scene.add(enemy.getMesh());
            }
        }

        // Spawn boss every 3rd wave
        if (this.wave % 3 === 0 && this.boss === null) {
            const bossPos = new THREE.Vector3(0, -15, 0);
            this.boss = new Boss(new ObjectPool(Bullet), bossPos);
            this.scene.add(this.boss.getMesh());
        }

        this.updateHUD();
    }

    public update(deltaTime: number): void {
        if (!this.isPlaying || this.isGameOver) return;

        // Apply hit-stop timescale
        const effectiveDelta = deltaTime * this.vfx.hitStop.update(deltaTime);

        // Update input
        this.input.update();

        // Update player
        if (this.player && this.player.active) {
            this.player.update(effectiveDelta, this.PLAYER_SPEED);

            // Player shooting
            if (this.input.isActionPressed('shoot') && this.player.canShoot()) {
                this.shootBullet(this.player.position.clone(), -400, 'player');
                this.player.lastShotTime = effectiveDelta;
            }
        }

        // Update enemies
        let edgeReached = false;
        const leftEdge = -32;
        const rightEdge = 32;

        for (const enemy of this.enemies) {
            if (!enemy.active) continue;

            enemy.update(effectiveDelta, this.wave);

            // Check edge
            if (enemy.position.x <= leftEdge || enemy.position.x >= rightEdge) {
                edgeReached = true;
            }

            // Enemy shooting
            if (Math.random() < 0.01 * this.wave && enemy.canShoot()) {
                const bulletPos = enemy.position.clone();
                bulletPos.y -= 2;
                this.shootBullet(bulletPos, -250, 'enemy');
                enemy.lastShotTime = effectiveDelta;
            }
        }

        // Boss shooting (if exists)
        if (this.boss && this.boss.active) {
            this.boss.update(effectiveDelta, this.wave);

            if (Math.random() < 0.02 * this.wave && this.boss.canShoot()) {
                const bulletPos = this.boss.position.clone();
                bulletPos.y -= 3;
                this.shootBullet(bulletPos, -300, 'enemy');
                this.boss.lastShotTime = effectiveDelta;
            }

            // Check boss edge
            if (this.boss.position.x <= leftEdge || this.boss.position.x >= rightEdge) {
                edgeReached = true;
            }
        }

        // Handle enemy formation shift
        if (edgeReached && this.enemies.some(e => e.active)) {
            const direction = -1; // Flip direction

            for (const enemy of this.enemies) {
                if (enemy.active) {
                    enemy.position.x += direction * 5;
                }
            }

            if (this.boss && this.boss.active) {
                this.boss.position.x += direction * 5;
            }

            // Drop down
            for (const enemy of this.enemies) {
                if (enemy.active) {
                    enemy.position.y -= this.ENEMY_DROP_DISTANCE;
                }
            }

            if (this.boss && this.boss.active) {
                this.boss.position.y -= this.ENEMY_DROP_DISTANCE;
            }

            // Check loss condition
            const lowestEnemy = Math.max(
                ...this.enemies.filter(e => e.active).map(e => e.position.y),
                this.boss?.position.y || -100
            );

            if (lowestEnemy > -25) {
                this.triggerGameOver();
                return;
            }
        }

        // Update bullets
        for (const bullet of this.bullets) {
            if (!bullet.active) continue;

            bullet.update(effectiveDelta);

            // Remove if out of bounds
            if (bullet.position.y > 35 || bullet.position.y < -35) {
                bullet.active = false;
                this.scene.remove(bullet.getMesh());
            }
        }

        // Collision detection
        this.checkCollisions();

        // Update VFX systems
        this.vfx.particles.update(effectiveDelta);
        this.vfx.trails.update(effectiveDelta);
        this.vfx.shockwaves.update(effectiveDelta);
        this.vfx.floatingTexts.update(effectiveDelta);

        // Update combo timer
        if (this.comboCount > 0) {
            this.comboTimer -= effectiveDelta;
            if (this.comboTimer <= 0) {
                this.resetCombo();
            }
        }

        // Check win condition
        const aliveEnemies = this.enemies.filter(e => e.active).length;
        const bossAlive = this.boss?.active || false;

        if (aliveEnemies === 0 && !bossAlive) {
            this.triggerWin();
        }

        // Update camera shake
        const shakeVector = this.vfx.shake.update(effectiveDelta);
        this.camera.position.x += shakeVector.x;
        this.camera.position.y += shakeVector.y;

        // Apply hit-stop to game loop timescale
        this.setTimescale(this.vfx.hitStop.getTimescale());
    }

    private shootBullet(position: Vector3, velocityY: number, ownerType: 'player' | 'enemy'): void {
        const bullet = new Bullet(position, velocityY);
        this.bullets.push(bullet);
        this.scene.add(bullet.getMesh());

        // Add motion trail
        if (ownerType === 'player') {
            this.vfx.trails.addTrail(position.clone(), 0.5);
        }
    }

    private checkCollisions(): void {
        const playerBulletList = this.bullets.filter(b => b.ownerType === 'player' && b.active);
        const enemyBulletList = this.bullets.filter(b => b.ownerType === 'enemy' && b.active);

        // Player bullets hitting enemies
        for (const bullet of playerBulletList) {
            if (!bullet.active) continue;

            // Check against regular enemies
            for (const enemy of this.enemies) {
                if (!enemy.active) continue;

                const dist = bullet.position.distanceTo(enemy.position);
                if (dist < 3.5) {
                    bullet.active = false;
                    this.scene.remove(bullet.getMesh());

                    // Kill enemy
                    enemy.takeDamage(1);
                    this.createExplosion(enemy.position, enemy.type === EnemyType.ELITE ? '#FF00FF' : '#00FF00');

                    if (!enemy.active) {
                        this.scene.remove(enemy.getMesh());
                        this.addScore(enemy.scoreValue);
                        this.incrementCombo();

                        // Chance for power-up drop (5%)
                        if (Math.random() < 0.05) {
                            this.spawnPowerUp(enemy.position.clone());
                        }
                    }

                    break;
                }
            }

            // Check against boss
            if (!bullet.active && this.boss?.active) continue;

            if (this.boss?.active) {
                const dist = bullet.position.distanceTo(this.boss.position);
                if (dist < 6) {
                    bullet.active = false;
                    this.scene.remove(bullet.getMesh());

                    this.boss.takeDamage(1);
                    this.createExplosion(this.boss.position, '#FFD700');

                    if (!this.boss.active) {
                        this.scene.remove(this.boss!.getMesh());
                        this.addScore(100);
                        this.incrementCombo();
                        this.boss = null;

                        // Spawn new wave after boss death
                        setTimeout(() => {
                            this.wave++;
                            this.spawnWave();
                        }, 2000);
                    }

                    break;
                }
            }
        }

        // Enemy bullets hitting player
        if (this.player?.active) {
            for (const bullet of enemyBulletList) {
                if (!bullet.active) continue;

                const dist = bullet.position.distanceTo(this.player.position);
                if (dist < 3) {
                    bullet.active = false;
                    this.scene.remove(bullet.getMesh());

                    this.takeDamage();
                    break;
                }
            }
        }
    }

    private createExplosion(position: Vector3, colorHex: string): void {
        const color = new Color(colorHex);

        // Particle burst
        this.vfx.particles.spawnExplosion(position.clone(), 20, color);

        // Camera shake based on explosion intensity
        this.vfx.shake.trigger(1.5);

        // Hit-stop for impact
        this.vfx.hitStop.trigger(0.08);

        // Shockwave ring
        this.vfx.shockwaves.spawn(position.clone(), 2);

        // Floating score text
        const points = Math.floor(Math.random() * 10) + 10;
        this.vfx.floatingTexts.spawn(position.clone(), `+${points}`, color);
    }

    private spawnPowerUp(position: Vector3): void {
        // Simplified power-up - just visual for now
        const color = new Color('#FF00FF');
        this.vfx.particles.spawnExplosion(position, 10, color);
        this.vfx.floatingTexts.spawn(position.clone(), 'POWER-UP!', new Color('#FFFF00'));
    }

    private addScore(points: number): void {
        // Apply combo multiplier
        const multiplier = 1 + Math.min(this.comboCount * 0.2, 2);
        this.score += Math.floor(points * multiplier);

        if (this.score > this.highScore) {
            this.highScore = this.score;
            localStorage.setItem('spaceInvadersHighScore', this.score.toString());
        }

        this.updateHUD();
    }

    private incrementCombo(): void {
        this.comboCount++;
        this.comboTimer = 3.0; // 3 second window

        const comboEl = document.getElementById('combo-counter')!;
        comboEl.textContent = `x${this.comboCount}`;
        comboEl.classList.add('active');

        if (this.comboCount > 1) {
            this.vfx.floatingTexts.spawn(
                new THREE.Vector3(0, -25, 0),
                `COMBO x${this.comboCount}!`,
                new Color('#FFD700')
            );
        }
    }

    private resetCombo(): void {
        this.comboCount = 0;
        const comboEl = document.getElementById('combo-counter')!;
        comboEl.classList.remove('active');
    }

    private takeDamage(): void {
        this.lives--;
        this.resetCombo();

        // Camera shake and hit-stop
        this.vfx.shake.trigger(2.0);
        this.vfx.hitStop.trigger(0.15);

        // Explosion effect at player position
        if (this.player?.active) {
            this.createExplosion(this.player.position, '#FF0000');

            // Temporary invulnerability or respawn delay could go here

            if (this.lives <= 0) {
                this.triggerGameOver();
            } else {
                // Respawn player at center
                this.player.position.set(0, -28, 0);
            }
        }

        this.updateHUD();
    }

    private triggerGameOver(): void {
        this.isPlaying = false;
        this.isGameOver = true;

        const gameOverEl = document.getElementById('game-over')!;
        const finalScoreEl = document.getElementById('final-score')!;

        finalScoreEl.textContent = this.score.toString();
        gameOverEl.classList.remove('hidden');

        // Massive explosion effect
        if (this.player?.active) {
            this.createExplosion(this.player.position, '#FF0000');
            this.vfx.shockwaves.spawn(this.player.position.clone(), 5);
        }
    }

    private triggerWin(): void {
        this.isPlaying = false;

        // Victory celebration
        for (let i = 0; i < 10; i++) {
            setTimeout(() => {
                const pos = new THREE.Vector3(
                    (Math.random() - 0.5) * 60,
                    (Math.random() - 0.5) * 40,
                    0
                );
                this.vfx.particles.spawnExplosion(pos, 15, new Color('#FFD700'));
            }, i * 200);
        }

        // Show game over with victory message after delay
        setTimeout(() => {
            const gameOverEl = document.getElementById('game-over')!;
            const finalScoreEl = document.getElementById('final-score')!;

            finalScoreEl.textContent = `VICTORY! Score: ${this.score}`;
            gameOverEl.classList.remove('hidden');
        }, 3000);
    }

    private updateHUD(): void {
        document.getElementById('score-display')!.textContent = this.score.toString();
        document.getElementById('high-score-display')!.textContent = this.highScore.toString();
        document.getElementById('wave-display')!.textContent = this.wave.toString();
        document.getElementById('lives-display')!.textContent = this.lives.toString();
    }

    public showHighScore(): void {
        alert(`High Score: ${this.highScore}`);
    }

    private animate(): void {
        requestAnimationFrame(() => this.animate());

        if (!this.isPlaying && !this.isGameOver) return;

        this.update();

        // Render with post-processing
        if (this.composer) {
            this.composer.render();
        } else {
            this.renderer.render(this.scene, this.camera);
        }
    }

    public dispose(): void {
        // Dispose all entities
        if (this.player) {
            this.scene.remove(this.player.getMesh());
            this.player.dispose();
        }

        this.enemies.forEach(e => {
            this.scene.remove(e.getMesh());
            e.dispose();
        });

        this.bullets.forEach(b => {
